import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it, vi, type Mock } from 'vitest';
import { HydraServerClient } from '../src/generated/hydra-server-client';
import { makeClient, makeTokenClient, makeTransport, readSettings, requestUrl, ServerHttpError, settingsFetch } from '../src/lib/serverClient';
import { fetchAudit, fetchAuditJsonl } from '../src/lib/auditApi';
import { panelCall } from '../src/lib/panelApi';

const ROOT = join(__dirname, '..');

type Send = (url: string, init: RequestInit) => Promise<Response>;

function reply(status: number, body: unknown, bad = false): Mock<Send> {
  return vi.fn<Send>(async () => ({ ok: status < 300, status, json: async () => { if (bad) throw new Error('not json'); return body; } }) as unknown as Response);
}

describe('the transport of the app', () => {
  it('builds the url from the path and the query, leaving empty values out', () => {
    expect(requestUrl({ path: '/api/x', query: {} })).toBe('/api/x');
    expect(requestUrl({ path: '/api/x', query: { slot: '2', empty: '' } })).toBe('/api/x?slot=2');
  });

  it('sends a read without a body and delivers the answer', async () => {
    const send = reply(200, { online: true });
    const client = new HydraServerClient(makeTransport(send));
    expect(await client.getEcosystemNodeHealth({ query: { slot: '3' } })).toEqual({ online: true });
    expect(send).toHaveBeenCalledWith('/api/ecosystem/node-health?slot=3', { method: 'GET' });
  });

  it('sends a body as JSON', async () => {
    const send = reply(200, {});
    await makeTransport(send)({ method: 'POST', path: '/api/p', query: {}, headers: {}, body: { a: 1 }, access: 'admin' });
    expect(send).toHaveBeenCalledWith('/api/p', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{"a":1}' });
  });

  it('sends a binary body as a Blob of its own media type and reads a text answer', async () => {
    const send = vi.fn<Send>(async () => ({ ok: true, status: 200, json: async () => ({}), text: async () => 'line one\nline two' }) as unknown as Response);
    await makeTransport(send)({ method: 'POST', path: '/api/b', query: {}, headers: {}, body: new Uint8Array([1, 2, 3]), access: 'admin', contentType: 'application/octet-stream' });
    const init = send.mock.calls[0][1];
    expect(init.headers).toEqual({ 'Content-Type': 'application/octet-stream' });
    expect(init.body).toBeInstanceOf(Blob);
    expect((init.body as Blob).size).toBe(3);
    expect(await makeTransport(send)({ method: 'GET', path: '/api/t', query: {}, headers: {}, body: undefined, access: 'admin', responseType: 'text' })).toBe('line one\nline two');
  });

  it('hands back the response headers a WithHeaders call names', async () => {
    const send = vi.fn<Send>(async () => ({ ok: true, status: 200, json: async () => ({ a: 1 }), headers: new Headers({ ETag: '"7"', 'X-Other': 'x' }) }) as unknown as Response);
    expect(await new HydraServerClient(makeTransport(send)).getSettingsWithHeaders()).toEqual({ body: { a: 1 }, headers: { ETag: '"7"' } });
  });

  it('sends the headers of the route next to the body', async () => {
    const send = reply(200, {});
    await makeTransport(send)({ method: 'POST', path: '/api/p', query: {}, headers: { 'If-Match': '"3"', 'X-Controller-Id': 'c1' }, body: { a: 1 }, access: 'user' });
    expect(send).toHaveBeenCalledWith('/api/p', { method: 'POST', headers: { 'If-Match': '"3"', 'X-Controller-Id': 'c1', 'Content-Type': 'application/json' }, body: '{"a":1}' });
    await makeTransport(send)({ method: 'GET', path: '/api/q', query: {}, headers: { 'X-Correlation-Id': 'k' }, body: undefined, access: 'user' });
    expect(send).toHaveBeenLastCalledWith('/api/q', { method: 'GET', headers: { 'X-Correlation-Id': 'k' } });
  });

  it('throws the status of a refusal and delivers null for an answer that is not JSON', async () => {
    const client = new HydraServerClient(makeTransport(reply(403, null)));
    const error = await client.getEcosystemHealth().catch((e: unknown) => e);
    expect(error).toBeInstanceOf(ServerHttpError);
    expect((error as ServerHttpError).status).toBe(403);
    expect(await new HydraServerClient(makeTransport(reply(200, null, true))).getEcosystemHealth()).toBeNull();
  });

  it('keeps the body and the Retry-After header of a refusal with the error', async () => {
    const send = vi.fn<Send>(async () => ({ ok: false, status: 429, headers: new Headers({ 'Retry-After': '60' }), json: async () => ({ error: 'slow down' }) }) as unknown as Response);
    const error = await new HydraServerClient(makeTransport(send)).getEcosystemHealth().catch((e: unknown) => e) as ServerHttpError;
    expect(error.status).toBe(429);
    expect(error.body).toEqual({ error: 'slow down' });
    expect(error.retryAfter).toBe('60');
    const plain = await new HydraServerClient(makeTransport(reply(500, null, true))).getEcosystemHealth().catch((e: unknown) => e) as ServerHttpError;
    expect(plain.body).toBeNull();
    expect(plain.retryAfter).toBeNull();
  });

  it('makes a client that carries the token it is handed, and none without one', async () => {
    const fetchMock = vi.fn(async (_url: string, _init?: RequestInit) => ({ ok: true, status: 200, json: async () => [] }) as unknown as Response);
    vi.stubGlobal('fetch', fetchMock);
    await makeTokenClient('tok').getTelemetryQuery({ query: { kind: 'temp', start: '5' } });
    expect(fetchMock).toHaveBeenLastCalledWith('/api/telemetry/query?kind=temp&start=5', { method: 'GET', headers: { Authorization: 'Bearer tok' } });
    await makeTokenClient(null).getTelemetryAggregate({ query: { bucketMs: '1000', agg: 'avg' } });
    expect(fetchMock).toHaveBeenLastCalledWith('/api/telemetry/aggregate?bucketMs=1000&agg=avg', { method: 'GET', headers: {} });
    await makeTokenClient('tok').postUploadWork({ body: { folderPath: 'WORKS/A', fileName: 'a.json', content: [1] } });
    const [url, init] = fetchMock.mock.calls[2] as unknown as [string, RequestInit];
    expect(url).toBe('/api/upload-work');
    expect(init.headers).toEqual({ Authorization: 'Bearer tok', 'Content-Type': 'application/json' });
    expect(JSON.parse(String(init.body))).toEqual({ folderPath: 'WORKS/A', fileName: 'a.json', content: [1] });
    vi.unstubAllGlobals();
  });

  it('builds a client over the given fetch function', async () => {
    const send = reply(200, { users: [] });
    expect(await makeClient(send).getUsers()).toEqual({ users: [] });
    expect(send).toHaveBeenCalledWith('/api/users', { method: 'GET' });
  });

  it('lets a network failure through as it is', async () => {
    const send = vi.fn<Send>(async () => { throw new Error('down'); });
    await expect(new HydraServerClient(makeTransport(send)).getEcosystemHealth()).rejects.toThrow('down');
  });
});

describe('the vendored client', () => {
  const vendored = readFileSync(join(ROOT, 'src', 'generated', 'hydra-server-client.ts'), 'utf8').replace(/\r\n/g, '\n');

  it('has a method for every route of the contract it was generated from', () => {
    expect(vendored.match(/^ {2}\/\*\* (GET|POST|PUT|PATCH|DELETE) \//gm)?.length ?? 0).toBeGreaterThanOrEqual(140);
  });

  const sdk = process.env.HYDRA_UMC_SDK_DIR || join(ROOT, '..', 'HYDRA-UMC-SDK');
  const generated = join(sdk, 'generated', 'hydra-server-client.ts');
  it.skipIf(!existsSync(generated))('is the file of the SDK', () => {
    // the only difference is the constructor, written without a parameter property (the app compiles with erasableSyntaxOnly)
    const original = readFileSync(generated, 'utf8').replace(/\r\n/g, '\n');
    const field = '  private readonly transport: HydraTransport;\n  constructor(transport: HydraTransport) {\n    this.transport = transport;\n  }';
    expect(vendored).toBe(original.replace('  constructor(private readonly transport: HydraTransport) {}', field));
    expect(vendored).not.toContain('constructor(private');
  });
});

describe('the defensive read of the panels', () => {
  const failure = (status: number) => ({ ok: false, failure: status === 404 ? 'unsupported' : status === 403 ? 'forbidden' : 'http', status });
  it('tells a missing route, a refused account, a server error and a dead network apart', async () => {
    const parse = (data: unknown): unknown => data;
    for (const status of [404, 403, 500]) {
      expect(await panelCall(() => Promise.reject(new ServerHttpError(status)), parse)).toEqual(failure(status));
    }
    expect(await panelCall(() => Promise.reject(new Error('down')), parse)).toEqual({ ok: false, failure: 'network' });
  });

  it('reads an answer that is not JSON as an empty object', async () => {
    expect(await panelCall(() => Promise.resolve(null), data => data)).toEqual({ ok: true, value: {} });
    expect(await panelCall(() => Promise.resolve({ a: 1 }), data => data)).toEqual({ ok: true, value: { a: 1 } });
  });
});

describe('the reading of the shared settings', () => {
  it('hands back the tree with the ETag of the answer', async () => {
    const send = vi.fn<Send>(async () => ({ ok: true, status: 200, json: async () => ({ controllers: [] }), headers: new Headers({ ETag: '"9"' }) }) as unknown as Response);
    expect(await readSettings(makeClient(send))).toEqual({ status: 200, data: { controllers: [] }, etag: '"9"' });
    expect(send.mock.calls[0][0]).toBe('/api/settings');
  });

  it('keeps the status of a refusal and has no ETag', async () => {
    expect(await readSettings(makeClient(reply(401, { error: 'login' })))).toEqual({ status: 401, data: { error: 'login' }, etag: null });
  });

  it('reads an answer that is not JSON as no tree', async () => {
    const send = vi.fn<Send>(async () => ({ ok: true, status: 200, json: async () => { throw new Error('not json'); }, headers: new Headers() }) as unknown as Response);
    expect(await readSettings(makeClient(send))).toEqual({ status: 200, data: null, etag: null });
  });
});

describe('the save of the shared settings through the typed client', () => {
  const answer = (status: number, body: unknown, headers: Record<string, string> = {}) =>
    vi.fn<Send>(async () => ({ ok: status < 300, status, json: async () => body, headers: new Headers(headers) }) as unknown as Response);

  it('sends a PUT with the If-Match it is given and answers the new ETag', async () => {
    const send = answer(200, { success: true }, { ETag: '"8"' });
    const out = await settingsFetch(makeClient(send))('', { method: 'PUT', headers: { 'If-Match': '"7"' }, body: '{"a":1}' });
    expect(send).toHaveBeenCalledWith('/api/settings', { method: 'PUT', headers: { 'If-Match': '"7"', 'Content-Type': 'application/json' }, body: expect.anything() });
    expect(out.ok).toBe(true);
    expect(out.headers.get('ETag')).toBe('"8"');
    expect(await out.json()).toEqual({ success: true });
  });

  it('reads with a GET and a POST goes without If-Match', async () => {
    const get = answer(200, { a: 1 }, { ETag: '"1"' });
    expect(await (await settingsFetch(makeClient(get))('', {})).json()).toEqual({ a: 1 });
    expect(get.mock.calls[0][1]).toEqual({ method: 'GET' });
    const post = answer(200, { success: true });
    await settingsFetch(makeClient(post))('', { method: 'POST', body: '{"a":2}' });
    expect(post.mock.calls[0][1].method).toBe('POST');
    expect(post.mock.calls[0][1].headers).toEqual({ 'Content-Type': 'application/json' });
  });

  it('turns a refusal into a not-ok answer with its status and body, and lets a network failure through', async () => {
    const out = await settingsFetch(makeClient(answer(412, { error: 'stale' })))('', { method: 'PUT', headers: { 'If-Match': '"1"' }, body: '{}' });
    expect(out.ok).toBe(false);
    expect(out.status).toBe(412);
    expect(await out.json()).toEqual({ error: 'stale' });
    await expect(settingsFetch(makeClient(vi.fn<Send>(async () => { throw new Error('offline'); })))('', {})).rejects.toThrow('offline');
  });
});

describe('the reading of the audit record through the typed client', () => {
  it('asks for the filter as a query and reads the entries', async () => {
    const send = vi.fn<Send>(async () => ({ ok: true, status: 200, json: async () => ({ enabled: true, entries: [] }) }) as unknown as Response);
    const out = await fetchAudit({ limit: 50, type: 'claim', verify: true }, makeClient(send));
    expect(send.mock.calls[0][0]).toBe('/api/audit?limit=50&type=claim&verify=1');
    expect(out.read?.entries).toEqual([]);
  });

  it('keeps the refusal of a non-administrator and reads nothing', async () => {
    const out = await fetchAudit({}, makeClient(reply(403, { error: 'admin' })));
    expect(out.read).toBeNull();
    expect(out.result.ok).toBe(false);
  });

  it('asks for the lines as text with format=jsonl and without the verification', async () => {
    const send = vi.fn<Send>(async () => ({ ok: true, status: 200, text: async () => '{"seq":1}\n' }) as unknown as Response);
    expect(await fetchAuditJsonl({ limit: 5, verify: true }, makeClient(send))).toBe('{"seq":1}\n');
    expect(send.mock.calls[0][0]).toBe('/api/audit?limit=5&format=jsonl');
    expect(await fetchAuditJsonl({}, makeClient(reply(500, {})))).toBeNull();
  });
});
